//! Schema IR v1: model description, relaxed binding and typed coercion.
//!
//! The IR is generated by the Python layer from dataclasses and consumed by the engine.
//! It is the compatibility contract between both worlds and is versioned apart from the
//! package (see ADR 0004).

use std::collections::BTreeMap;

use serde::Deserialize;
use serde_json::{Map, Value as Json};

use crate::error::{Error, Result};
use crate::snapshot::Snapshot;
use crate::value::Value;

/// Version of the IR understood by this engine.
pub const IR_VERSION: &str = "keydex.schema/v1";

/// Model schema.
#[derive(Debug, Clone, Deserialize)]
pub struct Schema {
    /// Contract version (`keydex.schema/v1`).
    pub ir: String,
    /// Root node, normally a `struct`.
    pub root: Field,
}

impl Schema {
    /// Parses and validates a JSON IR.
    pub fn from_json(text: &str) -> Result<Self> {
        let schema: Self = serde_json::from_str(text).map_err(|err| Error::Parse {
            file: String::from("<schema>"),
            message: err.to_string(),
        })?;
        if schema.ir != IR_VERSION {
            return Err(Error::UnsupportedFormat { format: schema.ir });
        }
        Ok(schema)
    }
}

/// Schema node.
#[derive(Debug, Clone, Deserialize)]
pub struct Field {
    /// Type: `str`, `int`, `float`, `bool`, `any`, `struct`, `optional` or `list`.
    #[serde(rename = "type")]
    pub kind: String,
    /// `true` when the value must exist.
    #[serde(default)]
    pub required: bool,
    /// Default declared in the model (informative; the engine does not apply it).
    #[serde(default)]
    pub default: Option<Json>,
    /// Fields of the `struct`.
    #[serde(default)]
    pub fields: BTreeMap<String, Field>,
    /// Element of a `list`.
    #[serde(default)]
    pub items: Option<Box<Field>>,
    /// Inner type of an `optional`.
    #[serde(default)]
    pub inner: Option<Box<Field>>,
    /// Converter the Python layer must apply (`enum`, `path`, `decimal`, `uuid`).
    #[serde(default)]
    pub converter: Option<String>,
}

/// Validation error for a specific value.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ValidationError {
    /// Key path: `db.port`, `servers[0].host`.
    pub path: String,
    /// What is wrong.
    pub message: String,
}

impl std::fmt::Display for ValidationError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.path, self.message)
    }
}

/// Key present in the configuration that the schema does not use.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnknownKey {
    /// Path as it appears in the snapshot.
    pub path: String,
    /// Closest schema path, when there is one reasonably near.
    pub suggestion: Option<String>,
}

/// Returns the snapshot keys that no schema path recognises.
///
/// It is the safety net against the quietest failure of a migration: a misspelled
/// override that never applies.
#[must_use]
pub fn unknown_keys(snapshot: &Snapshot, schema: &Schema) -> Vec<UnknownKey> {
    let mut known = Vec::new();
    collect_leaf_paths(&schema.root, "", &mut known);

    snapshot
        .keys()
        .filter(|key| !is_known(&schema.root, key))
        .map(|key| UnknownKey {
            path: key.to_string(),
            suggestion: best_suggestion(key, &known),
        })
        .collect()
}

fn collect_leaf_paths(node: &Field, path: &str, out: &mut Vec<String>) {
    match node.kind.as_str() {
        "struct" => {
            for (name, child) in &node.fields {
                let child_path = if path.is_empty() {
                    name.clone()
                } else {
                    format!("{path}.{name}")
                };
                collect_leaf_paths(child, &child_path, out);
            }
        }
        "list" => {
            if let Some(items) = node.items.as_deref() {
                collect_leaf_paths(items, path, out);
            }
        }
        "optional" => {
            if let Some(inner) = node.inner.as_deref() {
                collect_leaf_paths(inner, path, out);
            }
        }
        _ => {
            if !path.is_empty() {
                out.push(path.to_string());
            }
        }
    }
}

fn is_known(root: &Field, path: &str) -> bool {
    let mut current = root;
    for segment in segments(path) {
        let node = unwrap_optional(current);
        if segment.starts_with('[') {
            if node.kind != "list" {
                return false;
            }
            match node.items.as_deref() {
                Some(items) => current = items,
                None => return false,
            }
        } else {
            if node.kind != "struct" {
                return false;
            }
            match node.fields.get(segment) {
                Some(field) => current = field,
                None => return false,
            }
        }
    }
    true
}

/// Splits `servers[0].host` into `["servers", "[0]", "host"]`.
fn segments(path: &str) -> Vec<&str> {
    let mut out = Vec::new();
    for part in path.split('.') {
        let Some(open) = part.find('[') else {
            out.push(part);
            continue;
        };
        if open > 0 {
            out.push(&part[..open]);
        }
        let mut rest = &part[open..];
        while let Some(close) = rest.find(']') {
            out.push(&rest[..=close]);
            rest = &rest[close + 1..];
            if rest.is_empty() {
                break;
            }
        }
    }
    out
}

fn unwrap_optional(mut node: &Field) -> &Field {
    while node.kind == "optional" {
        match node.inner.as_deref() {
            Some(inner) => node = inner,
            None => break,
        }
    }
    node
}

fn best_suggestion(unknown: &str, known: &[String]) -> Option<String> {
    let unknown_last = last_segment(unknown);
    let mut best: Option<(usize, &String)> = None;

    for candidate in known {
        let full = levenshtein(unknown, candidate);
        // Comparing the last segment too lets us suggest `name` when the user nested it
        // wrong (`app.name`).
        let last = levenshtein(unknown_last, last_segment(candidate)).saturating_add(1);
        let distance = full.min(last);
        if best.is_none_or(|(current, _)| distance < current) {
            best = Some((distance, candidate));
        }
    }

    match best {
        Some((distance, candidate)) if distance <= 2 => Some(candidate.clone()),
        _ => None,
    }
}

fn last_segment(path: &str) -> &str {
    path.rsplit('.').next().unwrap_or(path)
}

fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut previous: Vec<usize> = (0..=b.len()).collect();
    let mut current = vec![0usize; b.len() + 1];

    for (i, ca) in a.iter().enumerate() {
        current[0] = i + 1;
        for (j, cb) in b.iter().enumerate() {
            let cost = usize::from(ca != cb);
            let deletion = previous[j + 1] + 1;
            let insertion = current[j] + 1;
            let substitution = previous[j] + cost;
            current[j + 1] = deletion.min(insertion).min(substitution);
        }
        std::mem::swap(&mut previous, &mut current);
    }

    previous[b.len()]
}

/// Result of the coercion: the typed tree or the list of errors.
pub type Coerced = core::result::Result<Json, Vec<ValidationError>>;

/// Coerces and validates the snapshot against the schema.
///
/// Returns a JSON tree with the typed values. Missing fields that are not required are
/// omitted so Python can apply the dataclass defaults.
pub fn coerce(snapshot: &Snapshot, schema: &Schema) -> Coerced {
    let mut errors = Vec::new();
    let slot = node(&schema.root, "", snapshot, &mut errors);

    if !errors.is_empty() {
        return Err(errors);
    }

    Ok(match slot {
        Slot::Value(value) => value,
        Slot::Missing => Json::Null,
    })
}

enum Slot {
    Missing,
    Value(Json),
}

impl Slot {
    fn into_option(self) -> Option<Json> {
        match self {
            Self::Missing => None,
            Self::Value(value) => Some(value),
        }
    }
}

fn node(field: &Field, path: &str, snapshot: &Snapshot, errors: &mut Vec<ValidationError>) -> Slot {
    match field.kind.as_str() {
        "struct" => {
            let mut object = Map::new();
            for (name, child) in &field.fields {
                let child_path = if path.is_empty() {
                    name.clone()
                } else {
                    format!("{path}.{name}")
                };
                if let Some(value) = node(child, &child_path, snapshot, errors).into_option() {
                    object.insert(name.clone(), value);
                }
            }
            if object.is_empty() && !field.required {
                Slot::Missing
            } else {
                Slot::Value(Json::Object(object))
            }
        }
        "optional" => {
            if snapshot.get(path).is_none() {
                return Slot::Value(Json::Null);
            }
            match snapshot.get(path) {
                Some(Value::Null) => Slot::Value(Json::Null),
                _ => match field.inner.as_deref() {
                    Some(inner) => node(inner, path, snapshot, errors),
                    None => {
                        errors.push(ValidationError {
                            path: path.to_string(),
                            message: String::from("optional without inner type"),
                        });
                        Slot::Missing
                    }
                },
            }
        }
        "list" => list(field, path, snapshot, errors),
        _ => scalar(field, path, snapshot, errors),
    }
}

fn list(field: &Field, path: &str, snapshot: &Snapshot, errors: &mut Vec<ValidationError>) -> Slot {
    let Some(item) = field.items.as_deref() else {
        errors.push(ValidationError {
            path: path.to_string(),
            message: String::from("list without item type"),
        });
        return Slot::Missing;
    };

    let prefix = format!("{path}[");
    let mut indexed: Vec<(usize, String)> = Vec::new();
    for key in snapshot.keys_with_prefix(&prefix) {
        let Some(index) = key
            .strip_prefix(&prefix)
            .and_then(|rest| rest.strip_suffix(']'))
            .and_then(|digits| digits.parse::<usize>().ok())
        else {
            continue;
        };
        indexed.push((index, key.to_string()));
    }

    if indexed.is_empty() {
        if field.required {
            errors.push(ValidationError {
                path: path.to_string(),
                message: String::from("required list missing"),
            });
        }
        return Slot::Missing;
    }

    indexed.sort_by_key(|(index, _)| *index);
    let mut values = Vec::with_capacity(indexed.len());
    for (_, key) in indexed {
        if let Some(value) = node(item, &key, snapshot, errors).into_option() {
            values.push(value);
        } else {
            values.push(Json::Null);
        }
    }
    Slot::Value(Json::Array(values))
}

fn scalar(
    field: &Field,
    path: &str,
    snapshot: &Snapshot,
    errors: &mut Vec<ValidationError>,
) -> Slot {
    let Some(value) = snapshot.get(path) else {
        if field.required {
            errors.push(ValidationError {
                path: path.to_string(),
                message: String::from("required field missing"),
            });
        }
        return Slot::Missing;
    };

    match convert(field, value) {
        Ok(json) => Slot::Value(json),
        Err(message) => {
            errors.push(ValidationError {
                path: path.to_string(),
                message,
            });
            Slot::Missing
        }
    }
}

fn convert(field: &Field, value: &Value) -> core::result::Result<Json, String> {
    match field.kind.as_str() {
        "str" | "any" => Ok(Json::String(value.to_string())),
        "int" => match value {
            Value::Int(i) => Ok(Json::from(*i)),
            Value::Str(text) => text
                .parse::<i64>()
                .map(Json::from)
                .map_err(|_| format!("expected an integer, got {text:?}")),
            other => Err(format!("expected an integer, got {other:?}")),
        },
        "float" => match value {
            Value::Float(f) => Ok(Json::from(*f)),
            Value::Int(i) => {
                Ok(serde_json::Number::from_f64(*i as f64).map_or(Json::Null, Json::Number))
            }
            Value::Str(text) => text
                .parse::<f64>()
                .ok()
                .and_then(serde_json::Number::from_f64)
                .map(Json::Number)
                .ok_or_else(|| format!("expected a number, got {text:?}")),
            other => Err(format!("expected a number, got {other:?}")),
        },
        "bool" => match value {
            Value::Bool(b) => Ok(Json::Bool(*b)),
            Value::Str(text) => parse_bool(text)
                .map(Json::Bool)
                .ok_or_else(|| format!("expected a boolean, got {text:?}")),
            other => Err(format!("expected a boolean, got {other:?}")),
        },
        other => Err(format!("unknown schema type: {other}")),
    }
}

fn parse_bool(text: &str) -> Option<bool> {
    match text.trim().to_ascii_lowercase().as_str() {
        "true" | "yes" | "on" | "1" => Some(true),
        "false" | "no" | "off" | "0" => Some(false),
        _ => None,
    }
}

/// Matches environment variables against schema paths (relaxed binding).
///
/// With a schema there is no guessing: `APP_DB_HOST` matches `db.host` because the
/// normalised path matches, and `APP_DB__HOST` matches explicitly. An exact path match
/// wins; only when it does not exist is the relaxed form used. If two schema paths tie,
/// [`Error::AmbiguousBinding`] is returned.
pub fn bind_env(
    root: &Field,
    env: &BTreeMap<String, String>,
    prefix: &str,
) -> Result<Vec<(String, String)>> {
    let mut dotted: BTreeMap<String, Vec<String>> = BTreeMap::new();
    let mut relaxed: BTreeMap<String, Vec<String>> = BTreeMap::new();
    collect_paths(root, "", &mut dotted, &mut relaxed);

    let wanted = prefix.to_ascii_uppercase();
    let mut bindings = Vec::new();

    for (name, value) in env {
        let upper = name.to_ascii_uppercase();
        let Some(rest) = upper.strip_prefix(&wanted) else {
            continue;
        };
        if rest.is_empty() {
            continue;
        }
        let relaxed_key = rest.to_ascii_lowercase();
        let dotted_key = relaxed_key.replace("__", ".");

        let candidates = dotted
            .get(&dotted_key)
            .or_else(|| relaxed.get(&relaxed_key));

        let Some(paths) = candidates else {
            continue;
        };
        match paths.as_slice() {
            [only] => bindings.push((only.clone(), value.clone())),
            _ => {
                return Err(Error::AmbiguousBinding {
                    env_var: name.clone(),
                    candidates: paths.clone(),
                });
            }
        }
    }

    bindings.sort_by(|a, b| a.0.cmp(&b.0));
    Ok(bindings)
}

fn collect_paths(
    node: &Field,
    path: &str,
    dotted: &mut BTreeMap<String, Vec<String>>,
    relaxed: &mut BTreeMap<String, Vec<String>>,
) {
    match node.kind.as_str() {
        "struct" => {
            for (name, child) in &node.fields {
                let child_path = if path.is_empty() {
                    name.clone()
                } else {
                    format!("{path}.{name}")
                };
                collect_paths(child, &child_path, dotted, relaxed);
            }
        }
        // Lists are not mapped from the environment in this version.
        "list" => {}
        "optional" => {
            if let Some(inner) = node.inner.as_deref() {
                collect_paths(inner, path, dotted, relaxed);
            }
        }
        _ => {
            if !path.is_empty() {
                dotted
                    .entry(path.to_string())
                    .or_default()
                    .push(path.to_string());
                relaxed
                    .entry(path.replace('.', "_"))
                    .or_default()
                    .push(path.to_string());
            }
        }
    }
}
